CREATE TABLE IF NOT EXISTS af_migration_history (id INTEGER PRIMARY KEY, name VARCHAR(255) NOT NULL, applied_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS af_site_settings (key_name VARCHAR(100) PRIMARY KEY, value_text TEXT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS af_license_installation (id VARCHAR(128) PRIMARY KEY, domain VARCHAR(255) NOT NULL, license_key VARCHAR(255) NOT NULL, status VARCHAR(32) NOT NULL DEFAULT 'active', created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS af_admin_users (id VARCHAR(128) PRIMARY KEY, email VARCHAR(320) NOT NULL UNIQUE, password_hash TEXT NOT NULL, role VARCHAR(32) NOT NULL DEFAULT 'owner', enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS af_admin_sessions (id VARCHAR(128) PRIMARY KEY, admin_user_id VARCHAR(128) NOT NULL, expires_at TIMESTAMP NOT NULL, created_at TIMESTAMP NOT NULL, last_seen_at TIMESTAMP NOT NULL);
